import { Component, inject } from '@angular/core';
import { Message } from 'app/features/notification/message/model/message.model';
import { MessageRepository } from 'app/features/notification/message/repository/message-repository.service';
import { ConfirmSelectionAction } from 'app/shared/toolkit/action/confirm-selection-action';

@Component({ selector: 'message-view-delete-selection-action', standalone: false, template: '' })
export class MessageViewDeleteSelectionActionComponent extends ConfirmSelectionAction<Message> {
  readonly name = 'deleteSelection';
  protected readonly scope = 'notification/message';
  protected readonly repository = inject(MessageRepository);

  protected runSelection(items: Message[]) {
    return this.repository.deleteSelection({ uids: items.map((item) => item.uid) });
  }
}
